                arr[b] = temp;
            }
            return arr;
        }

        public static Integer[] reversed(int size) {
            Integer[] arr = new Integer[size];
            for (int i = 0; i < size; i++) {
                arr[i] = size - i;
            }
            return arr;
        }

        public static Integer[] duplicates(int size) {
            Integer[] arr = new Integer[size];
            int unique = (int) Math.sqrt(size);
            for (int i = 0; i < size; i++) {
                arr[i] = random.nextInt(unique);
            }
            return arr;
        }
    }
